'use strict';

const interviewVocabulary = [
  ['IT','API endpoint','API نىڭ زىيارەت ئادرېسى','What is an API endpoint?','API نىڭ زىيارەت ئادرېسى دېگەن نېمە؟','An address where a client can call a specific API operation.','خېرىدار پروگراممىسى API نىڭ مەلۇم بىر مەشغۇلاتىنى چاقىرىدىغان ئادرېس.','The API endpoint returns a list of users.','API نىڭ زىيارەت ئادرېسى ئىشلەتكۈچىلەر تىزىملىكىنى قايتۇرىدۇ.'],
  ['IT','HTTP status code','HTTP ھالەت كودى','What does an HTTP status code tell you?','HTTP ھالەت كودى نېمىنى بىلدۈرىدۇ؟','It indicates the result of a request, such as success or a missing resource.','ئۇ تەلەپنىڭ مۇۋەپپەقىيەتلىك بولغانلىقى ياكى بايلىقنىڭ تېپىلمىغانلىقىدەك نەتىجىسىنى كۆرسىتىدۇ.','An HTTP status code can indicate that a request failed.','HTTP ھالەت كودى تەلەپنىڭ مەغلۇپ بولغانلىقىنى بىلدۈرەلەيدۇ.'],
  ['IT','Authentication','كىملىك دەلىللەش','How does authentication differ from authorization?','كىملىك دەلىللەش بىلەن ھوقۇق بېرىشنىڭ پەرقى نېمە؟','Authentication verifies identity. Authorization determines what actions that identity may perform.','كىملىك دەلىللەش كىملىكنى تەكشۈرىدۇ. ھوقۇق بېرىش شۇ كىملىكنىڭ قايسى مەشغۇلاتلارنى قىلالايدىغانلىقىنى بەلگىلەيدۇ.','Authentication verifies the identity of a user.','كىملىك دەلىللەش ئىشلەتكۈچىنىڭ كىملىكىنى تەكشۈرىدۇ.'],
  ['IT','Cache invalidation','غەملەكنى ئىناۋەتتىن قالدۇرۇش','Why is cache invalidation needed?','غەملەكنى نېمە ئۈچۈن ئىناۋەتتىن قالدۇرۇش كېرەك؟','It prevents readers from continuing to use an outdated cached copy.','ئۇ ئوقۇغۇچىنىڭ ۋاقتى ئۆتكەن غەملەك نۇسخىسىنى داۋاملىق ئىشلىتىشىنىڭ ئالدىنى ئالىدۇ.','Cache invalidation removes stale copies from the cache.','غەملەكنى ئىناۋەتتىن قالدۇرۇش ۋاقتى ئۆتكەن نۇسخىلارنى غەملەكتىن چىقىرىۋېتىدۇ.'],
  ['IT','Database index','ساندان ئىندېكسى','What is the trade-off of adding a database index?','ساندان ئىندېكسى قوشۇشنىڭ پايدىسى ۋە بەدىلى نېمە؟','An index can speed up reads, while using storage and adding work to writes.','ئىندېكس سانلىق مەلۇمات ئوقۇشنى تېزلىتىدۇ، ئەمما ساقلاش ئورنى ۋە قوشۇمچە يېزىش مەشغۇلاتى تەلەپ قىلىدۇ.','A database index can make searches faster.','ساندان ئىندېكسى ئىزدەشنى تېزلىتەلەيدۇ.'],
  ['IT','SQL join','SQL جەدۋەللىرىنى باغلاش','How does a left join differ from an inner join?','سول تەرەپلىك باغلاش بىلەن ئىچكى باغلاشنىڭ پەرقى نېمە؟','An inner join keeps matches. A left join also keeps unmatched rows from the left table.','ئىچكى باغلاش ماس كەلگەن قۇرلارنى ساقلايدۇ. سول تەرەپلىك باغلاش سول جەدۋەلدىكى ماس كەلمىگەن قۇرلارنىمۇ ساقلايدۇ.','An SQL join combines rows from related tables.','SQL باغلاش مۇناسىۋەتلىك جەدۋەللەردىكى قۇرلارنى بىرلەشتۈرىدۇ.'],
  ['IT','Database transaction','ساندان مەشغۇلات بىرلىكى','Why group operations in a database transaction?','نېمە ئۈچۈن بىر نەچچە مەشغۇلاتنى بىر ساندان مەشغۇلات بىرلىكىگە كىرگۈزىمىز؟','It lets related operations commit together or roll back together.','ئۇ مۇناسىۋەتلىك مەشغۇلاتلارنى بىللە جەزملەشتۈرۈشكە ياكى بىكار قىلىشقا يول قويىدۇ.','A database transaction can update two records together.','بىر ساندان مەشغۇلات بىرلىكى ئىككى خاتىرىنى بىللە يېڭىلىيالايدۇ.'],
  ['IT','Idempotency','تەكرارلىغاندا نەتىجىنىڭ ئۆزگەرمەسلىكى','Why does idempotency matter when a request is retried?','تەلەپ قايتا ئەۋەتىلسە نېمە ئۈچۈن تەكرارلاشنىڭ نەتىجىگە تەسىر قىلماسلىقى مۇھىم؟','Repeating the same request has the same intended effect as applying it once.','ئوخشاش تەلەپنى تەكرارلاشنىڭ كۆزلەنگەن تەسىرى ئۇنى بىر قېتىم ئىجرا قىلغان بىلەن ئوخشاش بولىدۇ.','Idempotency makes retries safer.','تەكرارلاش نەتىجىنى ئۆزگەرتمىسە، قايتا سىناش بىخەتەررەك بولىدۇ.'],
  ['IT','Time complexity','ۋاقىت مۇرەككەپلىكى','What does time complexity measure?','ۋاقىت مۇرەككەپلىكى نېمىنى ئۆلچەيدۇ؟','It describes how the amount of work grows as the input gets larger.','ئۇ كىرگۈزۈلمە چوڭايغاندا مەشغۇلات مىقدارىنىڭ قانداق ئېشىدىغانلىقىنى ئىپادىلەيدۇ.','Time complexity helps us compare algorithms.','ۋاقىت مۇرەككەپلىكى ھېسابلاش ئۇسۇللىرىنى سېلىشتۇرۇشقا ياردەم بېرىدۇ.'],
  ['IT','Unit test','بىرلىك سىنىقى','What does a unit test check?','بىرلىك سىنىقى نېمىنى تەكشۈرىدۇ؟','It checks a small unit of behavior, such as one function.','ئۇ بىر فۇنكسىيەگە ئوخشاش كىچىك بىر بۆلەكنىڭ ھەرىكىتىنى تەكشۈرىدۇ.','A unit test checks one expected behavior.','بىرلىك سىنىقى كۈتۈلگەن بىر خىل ھەرىكەتنى تەكشۈرىدۇ.'],
  ['IT','Continuous integration','ئۈزلۈكسىز بىرلەشتۈرۈش','How does continuous integration help a team?','ئۈزلۈكسىز بىرلەشتۈرۈش ئەترەتكە قانداق ياردەم بېرىدۇ؟','Frequent code integration and automated checks expose failures early.','كودنى دائىم بىرلەشتۈرۈش ۋە ئاپتوماتىك تەكشۈرۈش خاتالىقلارنى بالدۇر بايقايدۇ.','Continuous integration runs checks when code changes.','ئۈزلۈكسىز بىرلەشتۈرۈش كود ئۆزگەرگەندە تەكشۈرۈش ئېلىپ بارىدۇ.'],
  ['IT','Load balancing','يۈك تەڭپۇڭلاشتۇرۇش','Why use load balancing across multiple servers?','نېمە ئۈچۈن كۆپ مۇلازىمېتىر ئارىسىدا يۈكنى تەڭپۇڭلاشتۇرىمىز؟','It distributes requests so one server does not have to handle all traffic.','ئۇ تەلەپلەرنى بۆلۈپ بېرىپ، بارلىق ئېقىمنىڭ بىرلا مۇلازىمېتىرغا چۈشۈپ قېلىشىنىڭ ئالدىنى ئالىدۇ.','Load balancing distributes requests across servers.','يۈك تەڭپۇڭلاشتۇرۇش تەلەپلەرنى مۇلازىمېتىرلار ئارىسىدا بۆلىدۇ.'],
  ['Machine Learning','Overfitting','ھەددىدىن زىيادە ماسلىشىش','How can you detect overfitting?','ھەددىدىن زىيادە ماسلىشىشنى قانداق بايقايسىز؟','The model performs well on training data and substantially worse on unseen validation data.','مودېل مەشىق سانلىق مەلۇماتىدا ياخشى، ئەمما بۇرۇن كۆرمىگەن دەلىللەش سانلىق مەلۇماتىدا كۆرۈنەرلىك ناچار نەتىجە بېرىدۇ.','Overfitting can hurt performance on new data.','ھەددىدىن زىيادە ماسلىشىش يېڭى مەلۇماتتىكى ئىقتىدارنى ناچارلاشتۇرىدۇ.'],
  ['Machine Learning','Data leakage','سانلىق مەلۇماتنىڭ سىرتتىن سىڭىپ كىرىشى','What is data leakage in model evaluation?','مودېل باھالاشتا سانلىق مەلۇماتنىڭ سىرتتىن سىڭىپ كىرىشى دېگەن نېمە؟','Training has access to information that would be unavailable at prediction time, making evaluation overly optimistic.','مەشىقلەندۈرۈشتە مۆلچەر ۋاقتىدا ئېرىشكىلى بولمايدىغان ئۇچۇر ئىشلىتىلىپ، باھالاش نەتىجىسى ئەمەلىيەتتىن يۇقىرى چىقىدۇ.','Data leakage can inflate evaluation scores.','سانلىق مەلۇماتنىڭ سىرتتىن سىڭىپ كىرىشى باھالاش نومۇرىنى سۈنئىي ئۆستۈرۈۋېتىدۇ.'],
  ['Machine Learning','Cross-validation','ئالماشتۇرۇپ دەلىللەش','Why use cross-validation?','نېمە ئۈچۈن ئالماشتۇرۇپ دەلىللەشنى ئىشلىتىمىز؟','Training and evaluation are repeated across splits to estimate performance more reliably.','ئىقتىدارنى ئىشەنچلىك مۆلچەرلەش ئۈچۈن، سانلىق مەلۇماتنىڭ ئوخشىمىغان بۆلەكلىرىدە مەشىقلەندۈرۈش ۋە باھالاش تەكرارلىنىدۇ.','We use cross-validation to estimate model performance.','مودېل ئىقتىدارىنى مۆلچەرلەش ئۈچۈن ئالماشتۇرۇپ دەلىللەشنى ئىشلىتىمىز.'],
  ['Machine Learning','Precision','مۆلچەرلەنگەن مۇسبەتلەرنىڭ توغرىلىق نىسبىتى','What does precision measure?','مۆلچەرلەنگەن مۇسبەتلەرنىڭ توغرىلىق نىسبىتى نېمىنى ئۆلچەيدۇ؟','It is the fraction of positive predictions that are correct.','ئۇ مودېل مۇسبەت دەپ مۆلچەرلىگەن نەتىجىلەر ئىچىدە ھەقىقەتەن مۇسبەت بولغانلىرىنىڭ نىسبىتى.','High precision means few positive predictions are false.','بۇ نىسبەت يۇقىرى بولسا، مۇسبەت دەپ مۆلچەرلەنگەنلەرنىڭ ئاز قىسمى خاتا بولىدۇ.'],
  ['Machine Learning','Recall','ھەقىقىي مۇسبەتلەرنى تېپىش نىسبىتى','When should you prioritize recall?','ھەقىقىي مۇسبەتلەرنى تېپىش نىسبىتىگە قاچان ئەھمىيەت بېرىسىز؟','Prioritize recall when missing a real positive case carries a high cost.','ھەقىقىي مۇسبەت ئەھۋالنى ئۆتكۈزۈۋېتىشنىڭ بەدىلى چوڭ بولغاندا، بۇ نىسبەتكە ئەھمىيەت بېرىڭ.','High recall means the model misses few real positives.','تېپىش نىسبىتى يۇقىرى بولسا، مودېل ھەقىقىي مۇسبەت ئەھۋاللارنىڭ ئاز قىسمىنى ئۆتكۈزۈۋېتىدۇ.'],
  ['Machine Learning','Class imbalance','تۈرلەرنىڭ تەڭپۇڭسىزلىقى','Why can accuracy be misleading with class imbalance?','تۈرلەر تەڭپۇڭ بولمىغاندا، توغرىلىق نىسبىتى نېمە ئۈچۈن قايمۇقتۇرىدۇ؟','A model can score highly by predicting the majority class while missing rare cases.','مودېل كۆپ سانلىق تۈرنى مۆلچەرلەپلا يۇقىرى نومۇر ئالالايدۇ، ئەمما ئاز ئۇچرايدىغان ئەھۋاللارنى ئۆتكۈزۈۋېتىدۇ.','Class imbalance can hide poor performance on rare cases.','تۈرلەرنىڭ تەڭپۇڭسىزلىقى ئاز ئۇچرايدىغان ئەھۋاللاردىكى ناچار ئىقتىدارنى يوشۇرۇپ قويالايدۇ.'],
  ['AI','Embedding','سىڭدۈرمە ۋېكتور','Why use an embedding for semantic search?','مەنىگە ئاساسەن ئىزدەشتە نېمە ئۈچۈن سىڭدۈرمە ۋېكتور ئىشلىتىمىز؟','An embedding represents an item as numbers that can be compared with other representations.','سىڭدۈرمە ۋېكتور بىر تۈرنى باشقا ئىپادىلەر بىلەن سېلىشتۇرغىلى بولىدىغان سانلار ئارقىلىق ئىپادىلەيدۇ.','An embedding represents a document as a vector.','سىڭدۈرمە ۋېكتور ھۆججەتنى ۋېكتور شەكلىدە ئىپادىلەيدۇ.'],
  ['AI','Tokenization','تېكىستنى كىچىك بۆلەكلەرگە ئايرىش','Why does a language model need tokenization?','تىل مودېلىغا تېكىستنى كىچىك بۆلەكلەرگە ئايرىش نېمە ئۈچۈن كېرەك؟','Tokenization splits text into units that can be mapped to numerical IDs.','بۇ جەريان تېكىستنى سانلىق كىملىككە ئايلاندۇرغىلى بولىدىغان بۆلەكلەرگە ئايرىيدۇ.','Tokenization splits text into smaller units.','تېكىستنى بۆلۈش يېزىقنى كىچىكرەك بۆلەكلەرگە ئايرىيدۇ.'],
  ['AI','Context window','كونتېكىست دائىرىسى','What limits a model’s context window?','مودېلنىڭ كونتېكىست دائىرىسى نېمە بىلەن چەكلىنىدۇ؟','It is limited by the number of tokens the model can handle for a request.','ئۇ مودېلنىڭ بىر تەلەپتە بىر تەرەپ قىلالايدىغان تېكىست بۆلەكلىرى سانى بىلەن چەكلىنىدۇ.','The context window limits how much text the model can consider.','كونتېكىست دائىرىسى مودېل نەزەرگە ئالالايدىغان تېكىست مىقدارىنى چەكلەيدۇ.'],
  ['AI','Retrieval-augmented generation','ئۇچۇر تېپىش ئارقىلىق كۈچەيتىلگەن جاۋاب ھاسىل قىلىش','How does retrieval-augmented generation work?','ئۇچۇر تېپىش ئارقىلىق كۈچەيتىلگەن جاۋاب ھاسىل قىلىش قانداق ئىشلەيدۇ؟','The system retrieves relevant sources and includes them as context before the model generates an answer.','سىستېما مۇناسىۋەتلىك مەنبەلەرنى تېپىپ، مودېل جاۋاب ھاسىل قىلىشتىن بۇرۇن ئۇلارنى ئارقا كۆرۈنۈش ئۇچۇرى قىلىپ قوشىدۇ.','Retrieval-augmented generation gives the model relevant source material.','ئۇچۇر تېپىش ئارقىلىق كۈچەيتىلگەن جاۋاب ھاسىل قىلىش مودېلغا مۇناسىۋەتلىك مەنبە تەمىنلەيدۇ.'],
  ['AI','Fine-tuning','مودېلنى ئىنچىكە تەڭشەش','When would you use fine-tuning?','مودېلنى قاچان ئىنچىكە تەڭشەيسىز؟','Fine-tuning updates a pretrained model using task-specific examples or data.','ئىنچىكە تەڭشەش مەلۇم بىر ۋەزىپىگە خاس مىسال ياكى سانلىق مەلۇمات بىلەن ئالدىن مەشىقلەندۈرۈلگەن مودېلنى يېڭىلايدۇ.','Fine-tuning can adapt a model to a specific task.','ئىنچىكە تەڭشەش مودېلنى مەلۇم بىر ۋەزىپىگە ماسلاشتۇرالايدۇ.'],
  ['AI','Hallucination','مەنبەسىز ياكى توقۇلما جاۋاب','How would you check for hallucination in an AI answer?','AI جاۋابىدا مەنبەسىز ياكى توقۇلما ئۇچۇر بار-يوقلۇقىنى قانداق تەكشۈرىسىز؟','Compare factual claims with reliable sources or ground-truth examples.','پاكىتقا دائىر قاراشلارنى ئىشەنچلىك مەنبەلەر ياكى توغرىلىقى ئالدىن بىلىنگەن مىساللار بىلەن سېلىشتۇرۇڭ.','A hallucination may sound convincing even when the claim is false.','توقۇلما جاۋابتىكى دەۋا خاتا بولسىمۇ قايىل قىلارلىق ئاڭلىنىشى مۇمكىن.']
].map(([topic, term, translation, question, questionUg, definition, explanation, example, meaning]) => {
  const start = example.toLowerCase().indexOf(term.toLowerCase());
  const blank = example.slice(start, start + term.length);
  return {topic, term, translation, question, questionUg, definition, explanation, example, meaning, blank};
});
